3	import { GAME_FAMILIES } from "@/lib/games";
4	import { currentPromo } from "@/lib/promotions";
5	import { firstMonthFreeAppliesTo } from "@/lib/promo-redemption";
6	import { annualDiscountPct } from "@/lib/annual-discount";
7	import { backupPlusMonthlyCents } from "@/lib/backup-upgrade";
8	import { extraDiskPerGbCents } from "@/lib/disk-expand";
9	import { AmbientField } from "@/components/marketing/AmbientField";
10	import { ReviewBadges } from "@/components/marketing/ReviewBadges";
11	import { POPULAR_TLDS } from "@/components/marketing/tlds";
12	import { ProductJsonLd, FaqJsonLd } from "@/components/marketing/StructuredData";
13	import {
14	  PricingExplorer,
15	  type ExplorerPlan,
16	  type ExplorerGameFamily,
17	  type ProductId,
18	} from "@/components/marketing/PricingExplorer";
19	
20	export const dynamic = "force-dynamic";
21	
22	export const metadata: Metadata = {
23	  title: "Pricing",
24	  description:
25	    "One place to compare every Nxeon product — Cloud VPS, game servers, shared web hosting, business email and domains. Live catalogue prices, monthly billing, no lock-in.",
26	  alternates: { canonical: "/pricing" },
27	};
28	
29	/* Deploy CTA target — the same href the previous pricing page's plan CTAs used. */
30	const DEPLOY_HREF = "/register";
31	const DOMAINS_HREF = "/domains";
32	
33	function gb(mb: number): string {
34	  return `${(mb / 1024).toFixed(mb % 1024 ? 1 : 0)} GB`;
35	}
36	/** Base MONTHLY price for a plan. VPS/Hosting store a monthly `priceCents`; Email &
37	 *  Game store it per `termMonths`, so normalise to a per-month figure. All display
38	 *  math downstream runs THIS through termPriceCents — the formula checkout charges. */
39	function monthlyOf(p: { priceCents: number; termMonths?: number }): number {
40	  const t = p.termMonths ?? 1;
41	  return t > 1 ? Math.round(p.priceCents / t) : p.priceCents;
42	}
43	
44	const INCLUDED: Record<ProductId, string[]> = {
45	  vps: ["Full root access", "Dedicated IPv4", "NVMe SSD", "DDoS protection", "Auto backups", "1-click reinstall"],
46	  game: ["DDoS protection", "Full control panel", "Instant deploy", "Game file manager", "Custom jar support"],
47	  hosting: ["Free SSL", "1-click WordPress", "Free migration", "cPanel included", "DDoS protection"],
48	  email: ["Webmail + IMAP/SMTP", "Spam & virus filtering", "Shared calendars & contacts", "Automatic MX/SPF setup"],
49	  domains: ["Free WhoisGuard privacy", "Full DNS management", "One-click VPS pointing", "Auto-renew"],
50	};
51	
52	const FAQ = [
53	  { q: "How does billing work across products?", a: "Every Nxeon product — VPS, game servers, shared hosting, business email and domains — is prepaid from your wallet balance, monthly by default. VPS also offers optional annual and multi-year terms at a discount. Whatever term you choose, services auto-renew at exactly that same price — the price you sign up at is the price you renew at — and nothing locks you in: cancel anytime and billing stops at the end of the current period." },
54	  { q: "Is the first month really free?", a: "On shared web hosting, yes — your first month is on us, then the plan renews at exactly the regular monthly price you see. The free-month offer applies to shared hosting only; VPS, game servers, business email and domains bill their regular price from month one." },
55	  { q: "Are the prices shown what I actually pay?", a: "Yes. Every price on this page is read live from the same catalogue the checkout charges from, so the number you see is the number you pay. Domain extensions show an indicative starting price — search a name for the exact live figure." },
56	];
